# frozen_string_literal: true

# nodoc: Autogenerated
class ApplicationController < ActionController::Base
  include BotChallengePage::Controller
  include FeatureFlaggable

  # Prevent CSRF attacks by raising an exception.
  # For APIs, you may want to use :null_session instead.
  protect_from_forgery with: :exception

  rescue_from CanCan::AccessDenied, with: :rescue_can_can

  def current_user
    @current_user ||= request.env['warden']&.user&.user_object || User.new
  end

  def authenticate_user!
    redirect_to root_url unless current_user.authenticated?
  end

  helper_method :current_user

  private

  def set_variant
    request.variant = :sidebar if params[:variant] == 'sidebar'
    request.variant = :modal if params[:modal]
  end

  def rescue_can_can(exception)
    logger.debug { "Access denied on #{exception.action} #{exception.subject.inspect}" }
    render status: :forbidden, plain: 'Access to this resource is denied.'
  end

  def redirect_after_action
    if params[:referrer]
      redirect_to post_action_redirect_url
    else
      redirect_back_or_to(root_url)
    end
  end

  def post_action_redirect_url
    referrer = URI.parse(params[:referrer].to_s)
    return params[:referrer].presence || root_url unless referrer.host || referrer.scheme
    return root_url if referrer.path.blank?

    path_on_this_host(referrer)
  rescue URI::InvalidURIError
    root_url
  end

  def path_on_this_host(url)
    URI::Generic.build(path: url.path.sub(%r{\A/+}, '/'), query: url.query, fragment: url.fragment).to_s
  end
end
